insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('4fa9978f-d974-5b9f-a301-6de2c94e5385', 'mastering-claude-ai', 'Mastering Claude AI — From Beginner to Advanced', 'Go from first prompt to reliable, repeatable Claude workflows for research, writing and analysis.', 'A structured path through Claude: how it reasons, how to brief it, how to work with long documents and data, and how to turn one-off chats into dependable workflows with Projects, artifacts and tools. Every module ends with a task you would actually do at work.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/mastering-claude-ai.svg', 750000, 'beginner', 'English', 960, array['Write clear, structured prompts that get consistent results first time', 'Analyse long reports, contracts and spreadsheets with Claude and verify its output', 'Use Projects, artifacts and file uploads to build reusable work setups', 'Design multi-step workflows for research, writing and decision support', 'Recognise hallucination risks and apply checks before you rely on an answer']::text[], array['A free or paid Claude account', 'No coding knowledge needed']::text[], '[{"question": "Who is this course for?", "answer": "Go from first prompt to reliable, repeatable Claude workflows for research, writing and analysis. Level: Beginner. Requirements: A free or paid Claude account; No coding knowledge needed."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, true, 1, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
