insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('0bcefaf4-8f2b-5fe3-a999-f18427e81891', 'aed9b027-079e-5f97-a337-b383432950f9', '4fa9978f-d974-5b9f-a301-6de2c94e5385', 'Written assignment: Prompt design case study', 'assignment', null, 90, 11, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('7a35fe8b-11eb-5f97-a19d-6e40699bd0d3', '4fa9978f-d974-5b9f-a301-6de2c94e5385', '0bcefaf4-8f2b-5fe3-a999-f18427e81891', 'aed9b027-079e-5f97-a337-b383432950f9', 'Prompt design case study', 'Rewrite three weak prompts from a marketing team, explain what each change fixes and predict the effect on the output.

**Questions**
1. Prompt A: ''Write something about our new product.'' Rewrite it as a complete brief and explain each change.
2. Prompt B: ''Summarise this report.'' (a 40-page market report). Rewrite it so the summary is verifiable.
3. Prompt C: ''Is this contract good?'' Rewrite it and predict how the output will change.', 'document', 'Rewrite three weak prompts from a marketing team, explain what each change fixes and predict the effect on the output.', null, 'Completed DOCX with rewritten prompts and reasoning', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:mastering-claude-ai/mastering-claude-ai-brief.docx', 'mastering-claude-ai-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('7a35fe8b-11eb-5f97-a19d-6e40699bd0d3', '{
 "questions": [
  {
   "question": "Prompt A: ''Write something about our new product.'' Rewrite it as a complete brief and explain each change.",
   "key_points": [
    "Adds role/audience, product facts as context, specific task, output format and length",
    "States tone and constraints (claims to avoid)",
    "Explains that context and format reduce guessing and rework"
   ]
  },
  {
   "question": "Prompt B: ''Summarise this report.'' (a 40-page market report). Rewrite it so the summary is verifiable.",
   "key_points": [
    "Asks for key findings with page/section references or quotes",
    "Specifies audience and length",
    "Asks Claude to flag uncertainties or missing data"
   ]
  },
  {
   "question": "Prompt C: ''Is this contract good?'' Rewrite it and predict how the output will change.",
   "key_points": [
    "Defines the reviewer''s perspective (our company) and what ''good'' means",
    "Requests clause-by-clause risks with references and severity",
    "Predicts structured, specific output instead of a vague opinion; notes legal review still needed"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
