insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('f93fe43e-63d1-5fe2-a68e-30a45b60082c', '4fa9978f-d974-5b9f-a301-6de2c94e5385', '126985d1-4dcb-5492-aefc-fb844ed1e82e', 'a3316feb-2bde-5c68-a544-a4202216a91f', 'Claude-assisted data clean-up', 'Use Claude to clean and summarise a messy customer feedback sheet, then record the prompts you used and the checks you ran.

**Tasks**
1. Clean the Channel and Comment columns (consistent case, trimmed spaces) in a new ''Clean'' sheet.
2. Use Claude to tag each comment with a theme and a sentiment (Positive/Neutral/Negative). Keep the tags in columns.
3. Calculate the average rating overall and by channel with formulas.
4. Write a 5-bullet summary of the main issues on a ''Summary'' sheet.
5. On a ''Prompts & checks'' sheet, paste the prompts you used and list how you checked Claude''s tagging (e.g. spot-check 10 rows).', 'file', 'Use Claude to clean and summarise a messy customer feedback sheet, then record the prompts you used and the checks you ran.', null, 'Cleaned workbook with a ''Summary'' sheet and a ''Prompts & checks'' sheet', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:mastering-claude-ai/mastering-claude-ai-workbook.xlsx', 'mastering-claude-ai-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
