Use a real or realistic business. Do not invent results: if something did not work, say so and explain what you learned.', 'practical', 'Set up a Claude Project for a real recurring task (weekly report, research brief, client emails) with instructions and reference files, and show three runs.', null, 'Screenshots or shared links of the Project setup and three outputs, plus a one-page explanation', 'Accepted: PDF, DOCX, PPTX, XLSX, PNG, JPG, ZIP. Maximum 20 MB.', '[{"criterion": "Completeness of deliverable", "points": 30, "description": "Everything requested in the deliverables list is submitted."}, {"criterion": "Quality of execution", "points": 30, "description": "The work meets a professional standard and applies course methods."}, {"criterion": "Evidence of real work", "points": 20, "description": "Screenshots, links, files or results show the work was actually done."}, {"criterion": "Reflection and learning", "points": 20, "description": "Honest reflection on what worked, what did not and what to change."}]'::jsonb, 100, 50, null, null, array['pdf', 'docx', 'pptx', 'xlsx', 'png', 'jpg', 'zip']::text[], true, true, true, 180, 12, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
