insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('d23cd188-5085-5fda-a7a2-cc14d6042a5a', '4fa9978f-d974-5b9f-a301-6de2c94e5385', 'f52f0121-414e-5201-ad90-d7bbb10349df', '0ac66db7-edb3-588d-aea6-7ed7bd5d328f', 'The confident wrong answer', 'Read the scenario, then write your response. State your assumptions, then give your diagnosis, recommended actions and the risks.', 'scenario', 'Scenario challenge: respond as the decision-maker.', 'Your manager forwards a Claude summary of a 60-page vendor contract that misstates the termination clause. Explain how this happened and design a review process that prevents it.', 'A written response of 400–700 words', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Diagnosis", "points": 30, "description": "Identifies the real causes, not just symptoms."}, {"criterion": "Recommended actions", "points": 30, "description": "Concrete, prioritised, realistic actions."}, {"criterion": "Risks and trade-offs", "points": 20, "description": "Considers risks, stakeholders and alternatives."}, {"criterion": "Communication", "points": 20, "description": "Clear, structured and persuasive for the stated audience."}]'::jsonb, 100, 50, null, null, array['docx', 'pdf']::text[], true, false, true, 60, 13, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_