insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('b9327773-6a80-5992-adcc-5381c0807068', 'd4e48ba0-081f-59c0-a16c-881ab4cde440', 'multi', null, 'Which practices reduce the risk of acting on a hallucinated answer? Select all that apply.', '["Asking Claude to quote the source passage", "Spot-checking figures against the original document", "Using a longer prompt", "Asking for confidence and uncertainties"]'::jsonb, null, '[0, 1, 3]'::jsonb, 'Quoting sources, spot-checks and asking for uncertainty all expose weak answers; length alone does not.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
