-- AI Productivity & Workflow Automation
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('894734b7-3ad6-5755-a29a-b93d2ad8e6ab', 'ai-productivity-workflow-automation', 'AI Productivity & Workflow Automation', 'Reclaim hours every week by redesigning your routine work around AI assistants and no-code automation.', 'Map where your time goes, decide which tasks AI should draft, check or fully automate, and build working automations with tools such as Zapier, Make and Google Workspace. You finish with a documented productivity system you actually use.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/ai-productivity-workflow-automation.svg', 750000, 'beginner', 'English', 960, array['Audit your week and identify tasks suited to AI assistance or automation', 'Use AI assistants for email, meetings, notes and document drafting', 'Build no-code automations that connect forms, sheets, email and AI', 'Design human checkpoints so automations stay accurate', 'Measure time saved and keep a maintainable workflow inventory']::text[], array['Google Workspace or Microsoft 365 account', 'Free Zapier or Make account (set up in module 3)']::text[], '[{"question": "Who is this course for?", "answer": "Reclaim hours every week by redesigning your routine work around AI assistants and no-code automation. Level: Beginner. Requirements: Google Workspace or Microsoft 365 account; Free Zapier or Make account (set up in module 3)."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 2, false, 2, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
