insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('30ad93ec-3c8d-5f37-aaac-4e40fbfd551c', 'e44d529d-4578-56cd-a388-8996085bb033', '894734b7-3ad6-5755-a29a-b93d2ad8e6ab', 'Written assignment: Automation decision memo', 'assignment', null, 90, 11, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('e525df5b-7da4-5dce-a7d1-248c15b19134', '894734b7-3ad6-5755-a29a-b93d2ad8e6ab', '30ad93ec-3c8d-5f37-aaac-4e40fbfd551c', 'e44d529d-4578-56cd-a388-8996085bb033', 'Automation decision memo', 'Answer the questions in the brief about which of a support team''s tasks should be drafted, checked or fully automated, and why.

**Questions**
1. A support team handles password resets, refund requests and product bug reports. Classify each as draft, check or automate, with reasons.
2. What data would you collect before automating, and why?
3. Describe two human checkpoints you would add and where.', 'document', 'Answer the questions in the brief about which of a support team''s tasks should be drafted, checked or fully automated, and why.', null, 'Completed DOCX memo', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:ai-productivity-workflow-automation/ai-productivity-workflow-automation-brief.docx', 'ai-productivity-workflow-automation-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('e525df5b-7da4-5dce-a7d1-248c15b19134', '{
 "questions": [
  {
   "question": "A support team handles password resets, refund requests and product bug reports. Classify each as draft, check or automate, with reasons.",
   "key_points": [
    "Password resets: automate via self-service with verification",
    "Refunds: AI drafts, human approves (money and judgement)",
    "Bug reports: AI triages and summarises, human checks before routing"
   ]
  },
  {
   "question": "What data would you collect before automating, and why?",
   "key_points": [
    "Volume and time per task",
    "Error rates and cost of mistakes",
    "Variation and exceptions in inputs"
   ]
  },
  {
   "question": "Describe two human checkpoints you would add and where.",
   "key_points": [
    "Approval before any external message or payment",
    "Exception queue for low-confidence or unusual cases",
    "Periodic sample review of automated outputs"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('f20e4e66-47fb-501b-aade-b92a366bd855', '6b96bc56-aa16-5273-a7aa-32c65e94c87b', '894734b7-3ad6-5755-a29a-b93d2ad8e6ab', 'Workbook assignment: Time audit workbook', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('f63aa98f-bc39-5e8b-a3da-71be28322bd5', '894734b7-3ad6-5755-a29a-b93d2ad8e6ab', 'f20e4e66-47fb-501b-aade-b92a366bd855', '6b96bc56-aa16-5273-a7aa-32c65e94c87b', 'Time audit workbook', 'Complete the provided time-audit workbook for one working week and score each task for automation potential using the formulas supplied.

**Tasks**
1. Add an ''Automation score'' column = Hours × AVERAGE(Repetitive, Rule-based) × (6 − Cost of error) / 5, using formulas.
2. Add a ''Decision'' column: Automate if score ≥ 6, Draft with AI if score ≥ 3, otherwise Keep human (use IFS or nested IF).
3. Sort or use SORTBY/TAKE to list the top-5 tasks by score on the Answers sheet.
4. Total the weekly hours in the ''Automate'' group.', 'file', 'Complete the provided time-audit workbook for one working week and score each task for automation potential using the formulas supplied.', null, 'Completed XLSX with the scoring sheet filled and a top-5 automation shortlist', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:ai-productivity-workflow-automation/ai-productivity-workflow-automation-workbook.xlsx', 'ai-productivity-workflow-automation-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
