insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('34aa4e76-8c5b-5f41-ab6a-7883af59ea3b', '7771d4d3-0f10-5c12-ae0f-1349591f0ea2', 'single', null, 'In a no-code automation, what starts the workflow?', '["An action", "A trigger", "A filter", "A webhook response"]'::jsonb, 1, null, 'A trigger (new form entry, new email, schedule) starts every run.', 1, 1) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('339e2ed6-3898-5ec7-aa16-ef4ddd8cb631', '7771d4d3-0f10-5c12-ae0f-1349591f0ea2', 'multi', null, 'Which tasks are usually good candidates for full automation? Select all that apply.', '["Copying form responses into a sheet", "Approving a refund for an angry customer", "Sending a weekly report from fixed data", "Negotiating a contract"]'::jsonb, null, '[0, 2]'::jsonb, 'Repetitive, rule-based tasks automate well; judgement-heavy tasks need a human.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('8217fe73-ade0-57ae-abe2-8a0ef2a6cd88', '7771d4d3-0f10-5c12-ae0f-1349591f0ea2', 'true_false', null, 'Adding an approval step before an AI-drafted email is sent is an example of a human-in-the-loop checkpoint.', '["True", "False"]'::jsonb, 0, null, 'Human review before external actions keeps automations safe.', 1, 3) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('71781d5b-266e-55f9-a365-2b799f0547be', '7771d4d3-0f10-5c12-ae0f-1349591f0ea2', 'match', null, 'Match each automation term to its meaning.', '{"left": ["Trigger", "Action", "Filter"], "right": ["Event that starts the run", "Condition that stops irrelevant runs", "Step the workflow performs"]}'::jsonb, null, '[0, 2, 1]'::jsonb, 'Trigger starts, action does, filter decides whether to continue.', 2, 4) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('2c1ab6c0-2dbc-504b-aec3-b39db293d4a1', '7771d4d3-0f10-5c12-ae0f-1349591f0ea2', 'scenario', 'Your automation fails every Monday because a colleague renames the sheet tab each week.', 'What is the most robust fix?', '["Ask the colleague to stop", "Point the automation at a fixed named range or ID", "Run it manually on Mondays", "Delete the automation"]'::jsonb, 1, null, 'Reference stable identifiers rather than names people edit.', 2, 5) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;

-- AI Agents and Autonomous Workflows
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('9865a636-75de-59d7-ad35-4cbafcb65ad4', 'ai-agents-autonomous-workflows', 'AI Agents and Autonomous Workflows', 'Understand, design and safely deploy AI agents that plan, use tools and complete multi-step tasks.', 'Learn what separates an agent from a chatbot, how tool use and planning work, and how to design agentic workflows with guardrails, evaluation and human oversight. You will design and test an agent for a real business process.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/ai-agents-autonomous-workflows.svg', 750000, 'advanced', 'English', 1440, array['Explain agent architecture: planning, tools, memory and feedback loops', 'Design tool definitions and instructions for reliable agent behaviour', 'Build an agentic workflow using a no-code or low-code platform', 'Create evaluation sets to test agent accuracy and failure modes', 'Apply guardrails, permissions and human approval for risky actions']::text[], array['Comfort with AI assistants (or our Claude course)', 'Basic spreadsheet skills; coding optional']::text[], '[{"question": "Who is this course for?", "answer": "Understand, design and safely deploy AI agents that plan, use tools and complete multi-step tasks. Level: Advanced. Requirements: Comfort with AI assistants (or our Claude course); Basic spreadsheet skills; coding optional."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, true, 3, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
