insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('a9543131-6c76-52d3-ae37-961e1ccc934e', '495038b6-8d8a-5f1d-ae23-2b12f829e3a7', '9865a636-75de-59d7-ad35-4cbafcb65ad4', 'Written assignment: Agent design review', 'assignment', null, 90, 11, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('56532317-bba3-54eb-a0fa-266c4f79f7a7', '9865a636-75de-59d7-ad35-4cbafcb65ad4', 'a9543131-6c76-52d3-ae37-961e1ccc934e', '495038b6-8d8a-5f1d-ae23-2b12f829e3a7', 'Agent design review', 'Answer the design-review questions for a proposed customer-support agent: tools, permissions, escalation rules and risks.

**Questions**
1. List the tools the support agent needs and the permission level for each.
2. Define escalation rules to a human.
3. Name three risks and a mitigation for each.', 'document', 'Answer the design-review questions for a proposed customer-support agent: tools, permissions, escalation rules and risks.', null, 'Completed DOCX design review', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:ai-agents-autonomous-workflows/ai-agents-autonomous-workflows-brief.docx', 'ai-agents-autonomous-workflows-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('56532317-bba3-54eb-a0fa-266c4f79f7a7', '{
 "questions": [
  {
   "question": "List the tools the support agent needs and the permission level for each.",
   "key_points": [
    "Read-only order lookup and knowledge base",
    "Draft-only reply tool; sending needs approval for sensitive cases",
    "No direct refund or account-deletion tool, or approval-gated"
   ]
  },
  {
   "question": "Define escalation rules to a human.",
   "key_points": [
    "Low confidence or repeated failure",
    "Money, legal, safety or angry/vulnerable customers",
    "Requests outside documented policy"
   ]
  },
  {
   "question": "Name three risks and a mitigation for each.",
   "key_points": [
    "Hallucinated policy → ground in knowledge base with citations",
    "Prompt injection from customer text → treat input as data, restrict tools",
    "Runaway actions/cost → limits, logging, monitoring"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('06e7ad82-4ca6-57af-ac9a-18ea797840cc', '676b5e12-329a-50fe-ad85-a72da0fb37ef', '9865a636-75de-59d7-ad35-4cbafcb65ad4', 'Workbook assignment: Agent evaluation sheet', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('d5e3c5a5-709c-5925-a62e-6eed7201791d', '9865a636-75de-59d7-ad35-4cbafcb65ad4', '06e7ad82-4ca6-57af-ac9a-18ea797840cc', '676b5e12-329a-50fe-ad85-a72da0fb37ef', 'Agent evaluation sheet', 'Use the provided evaluation workbook to score 20 agent runs against expected outcomes and calculate pass rate and failure categories.

**Tasks**
1. Calculate the overall pass rate with COUNTIF.
2. Calculate pass rate by task type.
3. Build a PivotTable (or COUNTIFS table) of failures by category.
4. Calculate average cost per passed run.
5. Write two recommendations based on the most common failure categories.', 'file', 'Use the provided evaluation workbook to score 20 agent runs against expected outcomes and calculate pass rate and failure categories.', null, 'Completed XLSX with pass rate formulas and a failure-mode pivot', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:ai-agents-autonomous-workflows/ai-agents-autonomous-workflows-workbook.xlsx', 'ai-agents-autonomous-workflows-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('d5e3c5a5-709c-5925-a62e-6eed7201791d', '{
 "expected": {
  "Overall pass rate (%)": 65.0,
  "Most common failure category": "Timeout",
  "Average cost per passed run (USD)": 0.21
