}', 'Inspect formulas, not just values. Accept rounding differences under 1%. Hard-coded answers where formulas were requested lose ''Live, correct formulas'' marks.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('095d2ab5-3888-5312-a89b-0b45d4fd42a1', 'bce35c40-5312-56fc-abca-2b6ecb0a6ef8', '9865a636-75de-59d7-ad35-4cbafcb65ad4', 'Practical project: Build and test an agent', 'assignment', null, 180, 12, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('a7722c0b-3022-5bf6-a1f7-df6ea3fc3469', '9865a636-75de-59d7-ad35-4cbafcb65ad4', '095d2ab5-3888-5312-a89b-0b45d4fd42a1', 'bce35c40-5312-56fc-abca-2b6ecb0a6ef8', 'Build and test an agent', 'Build an agent that completes a multi-step task (research brief, lead qualification, invoice triage) and test it on at least ten cases.

Use a real or realistic business. Do not invent results: if something did not work, say so and explain what you learned.', 'practical', 'Build an agent that completes a multi-step task (research brief, lead qualification, invoice triage) and test it on at least ten cases.', null, 'Link or screenshots of the agent, the test log and a reflection on failures', 'Accepted: PDF, DOCX, PPTX, XLSX, PNG, JPG, ZIP. Maximum 20 MB.', '[{"criterion": "Completeness of deliverable", "points": 30, "description": "Everything requested in the deliverables list is submitted."}, {"criterion": "Quality of execution", "points": 30, "description": "The work meets a professional standard and applies course methods."}, {"criterion": "Evidence of real work", "points": 20, "description": "Screenshots, links, files or results show the work was actually done."}, {"criterion": "Reflection and learning", "points": 20, "description": "Honest reflection on what worked, what did not and what to change."}]'::jsonb, 100, 50, null, null, array['pdf', 'docx', 'pptx', 'xlsx', 'png', 'jpg', 'zip']::text[], true, true, true, 180, 12, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('a7722c0b-3022-5bf6-a1f7-df6ea3fc3469', '{
 "must_include": [
  "Link or screenshots of the agent, the test log and a reflection on failures"
 ],
 "evidence": "Submission must include verifiable evidence (screenshots, links or files) of real work."
}', 'Do not reward claims without evidence. If evidence is missing or unverifiable, flag for human review.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('df5ffa16-bf8f-570b-ae2b-0df2b41e8855', '9e336f82-8d8c-5c4e-ae3b-bbed04b389fc', '9865a636-75de-59d7-ad35-4cbafcb65ad4', 'Scenario challenge: The agent with too much access', 'assignment', null, 60, 13, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('006a3625-067a-5515-aec2-a0e9302489a7', '9865a636-75de-59d7-ad35-4cbafcb65ad4', 'df5ffa16-bf8f-570b-ae2b-0df2b41e8855', '9e336f82-8d8c-5c4e-ae3b-bbed04b389fc', 'The agent with too much access', 'Read the scenario, then write your response. State your assumptions, then give your diagnosis, recommended actions and the risks.', 'scenario', 'Scenario challenge: respond as the decision-maker.', 'An operations agent with write access to the billing system issued duplicate refunds after a timeout. Explain what went wrong and propose controls.', 'Written incident analysis with a control plan', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Diagnosis", "points": 30, "description": "Identifies the real causes, not just symptoms."}, {"criterion": "Recommended actions", "points": 30, "description": "Concrete, prioritised, realistic actions."}, {"criterion": "Risks and trade-offs", "points": 20, "description": "Considers risks, stakeholders and alternatives."}, {"criterion": "Communication", "points": 20, "description": "Clear, structured and persuasive for the stated audience."}]'::jsonb, 100, 50, null, null, array['docx', 'pdf']::text[], true, false, true, 60, 13, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('006a3625-067a-5515-aec2-a0e9302489a7', '{
 "key_points": [
  "Cause: non-idempotent write action plus retries after timeout, excessive permissions",
  "Controls: idempotency keys, approval for refunds, least privilege, rate limits",
  "Monitoring and reconciliation; remediation of duplicates"
 ]
}', 'Strong answers cover the key points with specific, prioritised actions. Accept other sound approaches.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
