insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('7df112be-5dde-55bd-aeef-51003cb4f15b', '3795548f-1db6-53f3-a49c-35edc3349f6a', 'single', null, 'What most distinguishes an AI agent from a simple chatbot?', '["It uses a larger model", "It can plan and take actions with tools across steps", "It has a name", "It answers faster"]'::jsonb, 1, null, 'Agents plan and act through tools over multiple steps.', 1, 1) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('058bcd36-90ee-5957-a2fe-78b9756036fb', '3795548f-1db6-53f3-a49c-35edc3349f6a', 'multi', null, 'Which controls reduce the risk of harmful agent actions? Select all that apply.', '["Least-privilege tool permissions", "Human approval for irreversible actions", "Unlimited retries", "Logging every tool call"]'::jsonb, null, '[0, 1, 3]'::jsonb, 'Limit access, require approval for risky steps and keep audit logs.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('a500d08d-516b-5be7-a343-f2f94bb85f34', '3795548f-1db6-53f3-a49c-35edc3349f6a', 'true_false', null, 'An agent that passes five manual tests is ready for production without further evaluation.', '["True", "False"]'::jsonb, 1, null, 'You need a broader evaluation set covering edge cases and failure modes.', 1, 3) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('4ec7eabc-7d38-5ddb-a956-6db838a794be', '3795548f-1db6-53f3-a49c-35edc3349f6a', 'fill_blank', null, 'A curated set of inputs with expected outcomes used to measure an agent is called an ___ set.', null, null, '[["evaluation", "eval", "test"]]'::jsonb, 'Evaluation sets make agent quality measurable.', 1, 4) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('6fc52a7d-d9de-5718-a672-a63f1ab71f6e', '3795548f-1db6-53f3-a49c-35edc3349f6a', 'scenario', 'Your research agent sometimes cites sources that do not exist.', 'What is the best fix?', '["Tell it to stop lying", "Require it to retrieve and quote sources via a search tool and validate links", "Use a bigger font", "Remove citations entirely"]'::jsonb, 1, null, 'Grounding in retrieved sources plus validation addresses fabricated citations.', 2, 5) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;

-- Generative AI for Professionals
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('012a60bb-6a4c-554d-aecc-c73198f4d9a1', 'generative-ai-for-professionals', 'Generative AI for Professionals', 'A practical, tool-agnostic foundation for using generative AI well in any role.', 'For managers, analysts, consultants and specialists who want to use text, image and data AI tools confidently. Covers how generative models work, high-value use cases by function, quality control, ethics and how to lead AI adoption in a team.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/generative-ai-for-professionals.svg', 750000, 'beginner', 'English', 960, array['Explain how generative AI works in plain language to colleagues', 'Apply AI to writing, analysis, research, presentations and images', 'Evaluate output quality and set review standards', 'Handle data privacy, bias and intellectual property responsibly', 'Build an AI adoption plan for your team']::text[], array['Any modern AI assistant account', 'No technical background required']::text[], '[{"question": "Who is this course for?", "answer": "A practical, tool-agnostic foundation for using generative AI well in any role. Level: Beginner. Requirements: Any modern AI assistant account; No technical background required."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 2, false, 4, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
