**Questions**
1. Which tools would you approve for a 50-person firm and on what criteria?
2. Write three data-handling rules for staff.
3. How would you measure whether AI adoption is working after three months?', 'document', 'Answer the policy questions in the brief for a 50-person firm adopting AI assistants.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:generative-ai-for-professionals/generative-ai-for-professionals-brief.docx', 'generative-ai-for-professionals-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('0c0ec3de-ea36-56d1-a741-707229946bed', '{
 "questions": [
  {
   "question": "Which tools would you approve for a 50-person firm and on what criteria?",
   "key_points": [
    "Enterprise plans with data-use controls and admin settings",
    "Security/privacy review, data residency, retention terms",
    "Fit to actual use cases and cost"
   ]
  },
  {
   "question": "Write three data-handling rules for staff.",
   "key_points": [
    "No confidential client or personal data in unapproved tools",
    "Anonymise or minimise data when allowed",
    "Check outputs before external use; disclose where required"
   ]
  },
  {
   "question": "How would you measure whether AI adoption is working after three months?",
   "key_points": [
    "Time saved on target tasks (baseline vs after)",
    "Quality/error rates and review findings",
    "Adoption/usage and staff feedback"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
