insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('b6a05c40-b847-503b-a990-8551290c40be', '012a60bb-6a4c-554d-aecc-c73198f4d9a1', 'bc63938d-4ada-5c4e-a5c1-c6b7c11b5bec', '36a9c791-6da1-57d5-aead-b5c6f94796ac', 'Use-case prioritisation matrix', 'Score 15 candidate AI use cases in the workbook for value, effort and risk and produce a ranked shortlist.

**Tasks**
1. Add a ''Priority score'' column = 2 × Value − Effort − Risk.
2. Rank the use cases with RANK or SORT.
3. Create a scatter or bubble chart of Value vs Effort.
4. List your top 3 pilots on the Answers sheet with one line each on why.', 'file', 'Score 15 candidate AI use cases in the workbook for value, effort and risk and produce a ranked shortlist.', null, 'Completed XLSX with the scoring model and chart', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:generative-ai-for-professionals/generative-ai-for-professionals-workbook.xlsx', 'generative-ai-for-professionals-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
