-- AI-Powered Business Automation
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('8562e619-dae2-5b1a-aa45-790ed5a8be17', 'ai-powered-business-automation', 'AI-Powered Business Automation', 'Automate operations end to end — sales, support, finance and HR — with AI and integrations.', 'Move beyond personal productivity to department-level automation. Map business processes, quantify the return, and build automations for lead handling, support triage, invoice processing and onboarding with proper controls.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/ai-powered-business-automation.svg', 750000, 'intermediate', 'English', 1200, array['Map business processes and identify automation opportunities', 'Build a business case with costs, savings and payback period', 'Automate lead capture, support triage and document processing', 'Integrate CRMs, spreadsheets, email and AI services', 'Set controls, audit trails and ownership for automated processes']::text[], array['Familiarity with spreadsheets', 'Free accounts for an automation platform']::text[], '[{"question": "Who is this course for?", "answer": "Automate operations end to end — sales, support, finance and HR — with AI and integrations. Level: Intermediate. Requirements: Familiarity with spreadsheets; Free accounts for an automation platform."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 5, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
