insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('126cc720-3f99-5f21-a339-7986915be2e9', '8562e619-dae2-5b1a-aa45-790ed5a8be17', 'c467f9be-c265-5c80-a19c-58e3a3982049', '9aeda5ae-24c7-5910-a2c4-2dcb08f9a2e7', 'Process improvement case', 'Answer the case questions on a distributor''s order-to-cash process and recommend what to automate first.

**Questions**
1. Map the distributor''s order-to-cash steps and mark the biggest bottleneck.
2. Which step would you automate first and why?
3. What controls would you put around the automation?', 'document', 'Answer the case questions on a distributor''s order-to-cash process and recommend what to automate first.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:ai-powered-business-automation/ai-powered-business-automation-brief.docx', 'ai-powered-business-automation-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('126cc720-3f99-5f21-a339-7986915be2e9', '{
 "questions": [
  {
   "question": "Map the distributor''s order-to-cash steps and mark the biggest bottleneck.",
   "key_points": [
    "Order capture → credit check → fulfilment → invoicing → collection",
    "Identifies manual re-keying of orders/invoices as bottleneck",
    "Uses the case''s delay or error figures as evidence"
   ]
  },
  {
   "question": "Which step would you automate first and why?",
   "key_points": [
    "Highest volume, rule-based step with measurable savings",
    "Low risk and easy to reverse",
    "Quick payback to build credibility"
   ]
  },
  {
   "question": "What controls would you put around the automation?",
   "key_points": [
    "Exception queue and owner",
    "Audit log and reconciliation",
    "Monitoring with alerts and periodic review"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('1620399a-9450-5f15-a447-5d85fa947ba6', 'd3b1963f-e5eb-5b02-a475-d597c4aaba90', '8562e619-dae2-5b1a-aa45-790ed5a8be17', 'Workbook assignment: Automation ROI model', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('6941139e-1418-5b98-a450-4c582418832e', '8562e619-dae2-5b1a-aa45-790ed5a8be17', '1620399a-9450-5f15-a447-5d85fa947ba6', 'd3b1963f-e5eb-5b02-a475-d597c4aaba90', 'Automation ROI model', 'Complete the ROI workbook for automating invoice processing: hours saved, tool costs, payback period and three-year value.

**Tasks**
1. Calculate monthly manual processing cost.
2. Calculate monthly automated cost (including exceptions handled manually and the tool cost).
3. Calculate monthly saving and payback period in months.
4. Calculate three-year net value (36 × saving − implementation).
5. Add a sensitivity table showing payback if the exception rate is 5%, 12%, 20% and 30%.', 'file', 'Complete the ROI workbook for automating invoice processing: hours saved, tool costs, payback period and three-year value.', null, 'Completed XLSX with working formulas', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:ai-powered-business-automation/ai-powered-business-automation-workbook.xlsx', 'ai-powered-business-automation-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
