-- ChatGPT, Claude and Gemini — Practical AI Mastery
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('60970750-f94f-5b79-ae06-ecbb36f8a0a7', 'chatgpt-claude-gemini-practical-mastery', 'ChatGPT, Claude and Gemini — Practical AI Mastery', 'Know which assistant to use for which job, and get expert results from all three.', 'A side-by-side, task-based course on the three leading assistants. Compare their strengths for writing, research, data, coding help and multimodal work, learn each tool''s power features, and build a multi-tool workflow.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/chatgpt-claude-gemini-practical-mastery.svg', 750000, 'intermediate', 'English', 1200, array['Compare ChatGPT, Claude and Gemini on real tasks with a fair method', 'Use each tool''s power features: projects, custom assistants, file analysis', 'Choose the right tool per task and combine them in one workflow', 'Work with images, PDFs and spreadsheets across tools', 'Keep results reliable with verification habits']::text[], array['Free accounts on ChatGPT, Claude and Gemini']::text[], '[{"question": "Who is this course for?", "answer": "Know which assistant to use for which job, and get expert results from all three. Level: Intermediate. Requirements: Free accounts on ChatGPT, Claude and Gemini."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 2, false, 6, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
