insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('583f6857-2858-5f33-a2ca-e8438ae07ef4', '{
 "questions": [
  {
   "question": "A legal team needs long-contract review. Which assistant setup would you recommend and why?",
   "key_points": [
    "Long-context model with file upload (e.g., Claude Projects)",
    "Clause-referenced outputs and human legal review",
    "Enterprise data controls"
   ]
  },
  {
   "question": "A marketing team lives in Google Workspace. What do you recommend?",
   "key_points": [
    "Gemini in Workspace for in-doc drafting",
    "Second assistant for cross-checking or specialised tasks",
    "Brand voice guidance and review"
   ]
  },
  {
   "question": "How would you train a mixed team to choose the right tool per task?",
   "key_points": [
    "Task-to-tool guide with examples",
    "Shared prompt library",
    "Verification habits and when not to use AI"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
