insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('41c8ac71-32b7-5abd-a369-a684cfa10ba9', '60970750-f94f-5b79-ae06-ecbb36f8a0a7', 'c08b96d3-0d91-55b9-ae10-293e1a432615', 'f62a6c09-cde4-5ccf-acaa-4f0eb93cfbdc', 'Assistant benchmark sheet', 'Run the eight benchmark tasks in the workbook on all three assistants and score them with the rubric provided.

**Tasks**
1. Run each task on all three assistants with an identical prompt; paste prompts in a ''Prompts'' sheet.
2. Score each output with the rubric.
3. Calculate each assistant''s average with formulas.
4. Highlight the best tool per task with conditional formatting.
5. Write your recommendation for a team of analysts.', 'file', 'Run the eight benchmark tasks in the workbook on all three assistants and score them with the rubric provided.', null, 'Completed XLSX with scores, averages and a recommendation', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:chatgpt-claude-gemini-practical-mastery/chatgpt-claude-gemini-practical-mastery-workbook.xlsx', 'chatgpt-claude-gemini-practical-mastery-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('41c8ac71-32b7-5abd-a369-a684cfa10ba9', '{
 "expected": {
  "Note": "Scores are the student''s own; grade consistency between scores, evidence (prompts/notes) and recommendation. Formulas must compute averages."
