insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('8f59daa0-16ea-5ad3-abc3-9e923a36cee9', '60970750-f94f-5b79-ae06-ecbb36f8a0a7', '7af79ca6-1a48-5748-ad47-58e1bf8864a2', 'a5f99b8e-d500-535f-ab27-1edffa67fd3f', 'Multi-tool workflow', 'Design and run a workflow that uses at least two assistants for one deliverable (for example: research in one, drafting in another, checking in a third).

Use a real or realistic business. Do not invent results: if something did not work, say so and explain what you learned.', 'practical', 'Design and run a workflow that uses at least two assistants for one deliverable (for example: research in one, drafting in another, checking in a third).', null, 'Deliverable plus a process log with prompts and screenshots', 'Accepted: PDF, DOCX, PPTX, XLSX, PNG, JPG, ZIP. Maximum 20 MB.', '[{"criterion": "Completeness of deliverable", "points": 30, "description": "Everything requested in the deliverables list is submitted."}, {"criterion": "Quality of execution", "points": 30, "description": "The work meets a professional standard and applies course methods."}, {"criterion": "Evidence of real work", "points": 20, "description": "Screenshots, links, files or results show the work was actually done."}, {"criterion": "Reflection and learning", "points": 20, "description": "Honest reflection on what worked, what did not and what to change."}]'::jsonb, 100, 50, null, null, array['pdf', 'docx', 'pptx', 'xlsx', 'png', 'jpg', 'zip']::text[], true, true, true, 180, 12, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
