-- AI Tools for Entrepreneurs and Startups
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('17586f1d-3801-50ff-ae69-821b0925f802', 'ai-tools-for-entrepreneurs', 'AI Tools for Entrepreneurs and Startups', 'Validate ideas, build brands, sell and operate faster with a lean AI toolkit.', 'Designed for founders and early teams. Use AI for market research, customer interviews, positioning, landing pages, pitch decks, sales outreach and lean operations — while keeping judgement and customer contact firmly human.', (select id from public.categories where slug = 'ai-automation'), '/thumbnails/ai-tools-for-entrepreneurs.svg', 750000, 'beginner', 'English', 960, array['Research markets and competitors quickly and critically', 'Turn customer interviews into insights and positioning', 'Create brand assets, landing pages and pitch material with AI', 'Run AI-assisted outreach without spamming', 'Set up lean AI-powered operations for a small team']::text[], array['An idea or early-stage business (real or practice)']::text[], '[{"question": "Who is this course for?", "answer": "Validate ideas, build brands, sell and operate faster with a lean AI toolkit. Level: Beginner. Requirements: An idea or early-stage business (real or practice)."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 7, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
