insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('55b8a5c8-cdcf-5e4c-ab17-343007f07dd6', '17586f1d-3801-50ff-ae69-821b0925f802', 'e14fce7d-381c-540f-a37d-f3184a7cee08', 'babd9aaf-c386-5c7d-a3df-b9e8ddc16e9c', 'Positioning worksheet', 'Answer the positioning worksheet: customer, problem, alternatives, unique value and proof.

**Questions**
1. Who exactly is your customer and what problem do they have?
2. What alternatives do they use today and why are they inadequate?
3. What is your unique value and what proof do you have?', 'document', 'Answer the positioning worksheet: customer, problem, alternatives, unique value and proof.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:ai-tools-for-entrepreneurs/ai-tools-for-entrepreneurs-brief.docx', 'ai-tools-for-entrepreneurs-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('55b8a5c8-cdcf-5e4c-ab17-343007f07dd6', '{
 "questions": [
  {
   "question": "Who exactly is your customer and what problem do they have?",
   "key_points": [
    "Specific segment (not ''everyone'')",
    "Concrete, frequent, painful problem",
    "Evidence from conversations or data"
   ]
  },
  {
   "question": "What alternatives do they use today and why are they inadequate?",
   "key_points": [
    "Names real alternatives including doing nothing",
    "Specific shortcomings",
    "Switching costs considered"
   ]
  },
  {
   "question": "What is your unique value and what proof do you have?",
   "key_points": [
    "Clear differentiator tied to the problem",
    "Proof: pilots, pre-orders, interviews, metrics",
    "Honest about what is not yet proven"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('78f100f9-9d81-53d9-a732-08e80fc164e6', 'bb67522b-31ae-51d6-ac48-42a0818b2219', '17586f1d-3801-50ff-ae69-821b0925f802', 'Workbook assignment: Market sizing workbook', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('82be44a9-60a4-580e-aae7-19824c0056d3', '17586f1d-3801-50ff-ae69-821b0925f802', '78f100f9-9d81-53d9-a732-08e80fc164e6', 'bb67522b-31ae-51d6-ac48-42a0818b2219', 'Market sizing workbook', 'Complete the TAM–SAM–SOM workbook for your idea using cited sources and documented assumptions.

**Tasks**
1. Replace the example assumptions with your own for your idea and cite a source for each in a ''Sources'' column.
2. Calculate TAM, SAM and SOM in customers and in ₹ per year.
3. Add a bottom-up check: customers you can realistically reach per month × conversion × 36 months.
4. Explain any gap between top-down SOM and bottom-up estimate.', 'file', 'Complete the TAM–SAM–SOM workbook for your idea using cited sources and documented assumptions.', null, 'Completed XLSX with sources listed', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:ai-tools-for-entrepreneurs/ai-tools-for-entrepreneurs-workbook.xlsx', 'ai-tools-for-entrepreneurs-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('82be44a9-60a4-580e-aae7-19824c0056d3', '{
