insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('a1b60c1e-5e4b-5dd9-ac85-30f1eb4e84a8', '17586f1d-3801-50ff-ae69-821b0925f802', '2501019e-5c14-56a1-a1aa-228a8aedd0bf', '9facdf73-4937-529a-a516-3f098752a6a5', 'Investor asks: why now?', 'Read the scenario, then write your response. State your assumptions, then give your diagnosis, recommended actions and the risks.', 'scenario', 'Scenario challenge: respond as the decision-maker.', 'In a pitch meeting an investor asks why your startup will win now when others failed. Prepare your answer.', 'Written answer of 300–500 words', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Diagnosis", "points": 30, "description": "Identifies the real causes, not just symptoms."}, {"criterion": "Recommended actions", "points": 30, "description": "Concrete, prioritised, realistic actions."}, {"criterion": "Risks and trade-offs", "points": 20, "description": "Considers risks, stakeholders and alternatives."}, {"criterion": "Communication", "points": 20, "description": "Clear, structured and persuasive for the stated audience."}]'::jsonb, 100, 50, null, null, array['docx', 'pdf']::text[], true, false, true, 60, 13, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_te