insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('cdd85f6c-3b5d-529f-a073-8ec48cf195c3', '46afda99-bdd4-5ec1-a2c6-119dca399b0e', 'single', null, 'SOM stands for…', '["Serviceable Obtainable Market", "Standard Operating Model", "Sales Outreach Method", "Share of Mind"]'::jsonb, 0, null, 'SOM is the portion of the market you can realistically capture.', 1, 1) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('ba3a5cb2-af1a-5f68-a3eb-ff88dbea5962', '46afda99-bdd4-5ec1-a2c6-119dca399b0e', 'multi', null, 'Which AI uses keep outreach responsible? Select all that apply.', '["Researching each prospect", "Personalising genuinely", "Sending thousands of identical emails", "Honouring opt-outs"]'::jsonb, null, '[0, 1, 3]'::jsonb, 'Relevance and consent matter; mass identical sends damage reputation.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('cecfdddd-6720-5cae-ae4a-1c0c8c8bda56', '46afda99-bdd4-5ec1-a2c6-119dca399b0e', 'true_false', null, 'AI-generated interview summaries can replace talking to customers.', '["True", "False"]'::jsonb, 1, null, 'AI helps synthesise interviews, it cannot replace them.', 1, 3) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
