insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('cfc7f918-ec9b-5f5a-a45d-0217901d088a', '46afda99-bdd4-5ec1-a2c6-119dca399b0e', 'scenario', 'AI suggests a ₹10,000 crore market size for your niche app.', 'What should you do?', '["Put it in the deck", "Rebuild the estimate bottom-up from real customer counts and pricing", "Double it", "Remove market size"]'::jsonb, 1, null, 'Bottom-up estimates are more credible than unsupported top-down numbers.', 2, 5) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;

-- Digital Marketing Mastery
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('51d4b865-205a-5b51-af33-437c23d0fad7', 'digital-marketing-mastery', 'Digital Marketing Mastery', 'A complete, practical foundation in strategy, channels, content and measurement.', 'Learn how digital marketing fits together: strategy, audiences, search, social, email, paid media and analytics. You build a full channel plan and run a small campaign so you can talk about results, not just theory.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/digital-marketing-mastery.svg', 750000, 'beginner', 'English', 960, array['Build a marketing strategy from business goals to channel plan', 'Define audiences, personas and the customer journey', 'Run search, social, email and paid campaigns at small scale', 'Measure performance with the right KPIs and Google Analytics', 'Present a campaign plan and results with confidence']::text[], array['No prior marketing experience', 'A Google account']::text[], '[{"question": "Who is this course for?", "answer": "A complete, practical foundation in strategy, channels, content and measurement. Level: Beginner. Requirements: No prior marketing experience; A Google account."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, true, 8, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
