insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('afe971f5-1739-59fa-ad7a-c6b6b75470da', '51d4b865-205a-5b51-af33-437c23d0fad7', 'f87207f8-0440-58b5-a9da-c0d9d8d17362', '83dddc01-2679-5f85-ad3e-6611556c8b93', 'Marketing plan questions', 'Answer the planning questions for a D2C skincare brand launching in two cities.

**Questions**
1. Define the launch goals and KPIs for the two-city D2C skincare launch.
2. Describe the target persona and customer journey.
3. Propose a channel mix and budget split with reasons.', 'document', 'Answer the planning questions for a D2C skincare brand launching in two cities.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:digital-marketing-mastery/digital-marketing-mastery-brief.docx', 'digital-marketing-mastery-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('afe971f5-1739-59fa-ad7a-c6b6b75470da', '{
 "questions": [
  {
   "question": "Define the launch goals and KPIs for the two-city D2C skincare launch.",
   "key_points": [
    "SMART business goal (e.g., orders/revenue by a date)",
    "Funnel KPIs: reach, CTR, conversion rate, CAC, repeat rate",
    "City-level targets"
   ]
  },
  {
   "question": "Describe the target persona and customer journey.",
   "key_points": [
    "Demographics plus needs/skin concerns and buying triggers",
    "Journey stages with channels and messages",
    "Objections and trust builders"
   ]
  },
  {
   "question": "Propose a channel mix and budget split with reasons.",
   "key_points": [
    "Mix of paid social, search, creators, email/WhatsApp",
    "Budget weighted to channels matching intent and audience",
    "Test-and-learn reserve"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('69a2ace1-d674-548d-a585-1c1d05da7011', '2949498a-abae-59c5-a5b7-753f5134b9d0', '51d4b865-205a-5b51-af33-437c23d0fad7', 'Workbook assignment: Campaign performance analysis', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('c9924d0d-cf9c-582b-ab8e-76e9f3805640', '51d4b865-205a-5b51-af33-437c23d0fad7', '69a2ace1-d674-548d-a585-1c1d05da7011', '2949498a-abae-59c5-a5b7-753f5134b9d0', 'Campaign performance analysis', 'Analyse the campaign dataset in the workbook: calculate CTR, CPC, conversion rate and CPA by channel and identify where to shift budget.

**Tasks**
1. Build a channel summary (SUMIFS) with impressions, clicks, cost, conversions and revenue.
2. Calculate CTR, CPC, conversion rate, CPA and ROAS per channel.
3. Chart CPA by channel.
4. Recommend how to reallocate next month''s budget and justify it with the numbers.', 'file', 'Analyse the campaign dataset in the workbook: calculate CTR, CPC, conversion rate and CPA by channel and identify where to shift budget.', null, 'Completed XLSX with formulas and a budget recommendation', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:digital-marketing-mastery/digital-marketing-mastery-workbook.xlsx', 'digital-marketing-mastery-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
