insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('60da1b25-5335-5c65-aecf-65107df06e98', '51d4b865-205a-5b51-af33-437c23d0fad7', '6b566211-c72f-5a78-a5bc-f87ee3873088', 'd490aba1-ca74-50d2-a6e5-5565c892b52c', 'Run a mini campaign', 'Plan and run a small campaign (organic or paid) for a real or practice brand for at least seven days and report results.

Use a real or realistic business. Do not invent results: if something did not work, say so and explain what you learned.', 'practical', 'Plan and run a small campaign (organic or paid) for a real or practice brand for at least seven days and report results.', null, 'Campaign plan, creatives and a results report', 'Accepted: PDF, DOCX, PPTX, XLSX, PNG, JPG, ZIP. Maximum 20 MB.', '[{"criterion": "Completeness of deliverable", "points": 30, "description": "Everything requested in the deliverables list is submitted."}, {"criterion": "Quality of execution", "points": 30, "description": "The work meets a professional standard and applies course methods."}, {"criterion": "Evidence of real work", "points": 20, "description": "Screenshots, links, files or results show the work was actually done."}, {"criterion": "Reflection and learning", "points": 20, "description": "Honest reflection on what worked, what did not and what to change."}]'::jsonb, 100, 50, null, null, array['pdf', 'docx', 'pptx', 'xlsx', 'png', 'jpg', 'zip']::text[], true, true, true, 180, 12, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
