insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('9b731589-0bfb-5bc2-aee0-e9a2f4e416c9', '51d4b865-205a-5b51-af33-437c23d0fad7', 'bf9a8e3b-5261-5c1d-aaca-0fb727e9587d', '93dcbfa2-b4f7-560f-a386-bde649746787', 'Traffic up, sales flat', 'Read the scenario, then write your response. State your assumptions, then give your diagnosis, recommended actions and the risks.', 'scenario', 'Scenario challenge: respond as the decision-maker.', 'A brand''s website traffic rose 60% after a campaign but sales did not change. Diagnose likely causes and propose next steps.', 'Written diagnosis of 400–700 words', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Diagnosis", "points": 30, "description": "Identifies the real causes, not just symptoms."}, {"criterion": "Recommended actions", "points": 30, "description": "Concrete, prioritised, realistic actions."}, {"criterion": "Risks and trade-offs", "points": 20, "description": "Considers risks, stakeholders and alternatives."}, {"criterion": "Communication", "points": 20, "description": "Clear, structured and persuasive for the stated audience."}]'::jsonb, 100, 50, null, null, array['docx', 'pdf']::text[], true, false, true, 60, 13, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
