insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('5feb3d28-9583-5f0c-a37f-16859f135aa9', '8af3daba-ab71-5f4a-a238-0e54932dad08', 'single', null, 'CTR is calculated as…', '["Clicks ÷ Impressions", "Conversions ÷ Clicks", "Cost ÷ Clicks", "Impressions ÷ Reach"]'::jsonb, 0, null, 'Click-through rate = clicks / impressions.', 1, 1) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('c7898bb2-c8c2-5d26-a01c-86afd6c7e275', '8af3daba-ab71-5f4a-a238-0e54932dad08', 'multi', null, 'Which are owned channels? Select all that apply.', '["Company website", "Email list", "Google Ads", "Brand blog"]'::jsonb, null, '[0, 1, 3]'::jsonb, 'Owned channels are those you control; ads are paid.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('77c18972-d2ec-5267-ac67-0d47dca76420', '8af3daba-ab71-5f4a-a238-0e54932dad08', 'true_false', null, 'A high number of followers always means high sales.', '["True", "False"]'::jsonb, 1, null, 'Followers are a vanity metric unless they convert.', 1, 3) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('e0b14d3a-6783-5ba4-a36f-e4f2db98646f', '8af3daba-ab71-5f4a-a238-0e54932dad08', 'match', null, 'Match the metric to its formula.', '{"left": ["CPC", "Conversion rate", "CPA"], "right": ["Cost ÷ Conversions", "Conversions ÷ Clicks", "Cost ÷ Clicks"]}'::jsonb, null, '[2, 1, 0]'::jsonb, 'Core paid-media formulas.', 2, 4) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('232e3792-7b4b-52a5-a7e8-c8134b7e37d7', '8af3daba-ab71-5f4a-a238-0e54932dad08', 'scenario', 'Ads get many clicks but the landing page has a 90% bounce rate.', 'What should you test first?', '["Increase budget", "Message match between ad and landing page", "Change the logo", "Stop all ads permanently"]'::jsonb, 1, null, 'Mismatched promises cause bounces; align the page with the ad.', 2, 5) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;

-- AI-Powered Digital Marketing
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('a40ea0b7-ace4-52c2-ae05-c7fa39ffb262', 'ai-powered-digital-marketing', 'AI-Powered Digital Marketing', 'Use AI across research, content, creative, ads and analytics without losing your brand voice.', 'Bring AI into every stage of marketing: audience research, content calendars, ad creative variations, personalisation, SEO briefs and reporting. Learn workflows that keep quality, brand voice and compliance under control.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/ai-powered-digital-marketing.svg', 750000, 'intermediate', 'English', 1200, array['Use AI for audience research and insight generation', 'Produce on-brand content and creative variations at scale', 'Build AI-assisted SEO briefs and content calendars', 'Automate reporting and extract insights from campaign data', 'Set brand-voice and review standards for AI content']::text[], array['Basic digital marketing knowledge', 'Access to an AI assistant']::text[], '[{"question": "Who is this course for?", "answer": "Use AI across research, content, creative, ads and analytics without losing your brand voice. Level: Intermediate. Requirements: Basic digital marketing knowledge; Access to an AI assistant."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 9, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
