insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('9df7c6d9-e9eb-5dbb-a86b-4eb6795317a9', '52e80e08-7b1b-50bc-a139-320d6adfaf17', 'a40ea0b7-ace4-52c2-ae05-c7fa39ffb262', 'Workbook assignment: Ad variation test results', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('ac95ff50-75cc-5cbf-a3ca-a95ed4db0f0c', 'a40ea0b7-ace4-52c2-ae05-c7fa39ffb262', '9df7c6d9-e9eb-5dbb-a86b-4eb6795317a9', '52e80e08-7b1b-50bc-a139-320d6adfaf17', 'Ad variation test results', 'Analyse the A/B test workbook for 12 AI-generated ad variants and identify statistically meaningful winners.

**Tasks**
1. Calculate CTR and conversion rate (conversions ÷ clicks) per variant.
2. Compare each variant with V01 (control) using a two-proportion z-test on conversion rate; show the z-score and whether |z| ≥ 1.96.
3. Summarise performance by creative angle with AVERAGEIFS.
4. State which variants you would scale, pause or retest.', 'file', 'Analyse the A/B test workbook for 12 AI-generated ad variants and identify statistically meaningful winners.', null, 'Completed XLSX with test calculations', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:ai-powered-digital-marketing/ai-powered-digital-marketing-workbook.xlsx', 'ai-powered-digital-marketing-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
