-- Performance Marketing & Paid Advertising
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('5d9a9938-88d4-5c92-a45f-e3b9895491f8', 'performance-marketing-paid-advertising', 'Performance Marketing & Paid Advertising', 'Plan, launch and optimise profitable Google and Meta ad campaigns.', 'Go deep on paid acquisition: account structure, audiences, bidding, creative, landing pages, tracking and optimisation. Learn to manage budgets against unit economics so campaigns make money, not just clicks.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/performance-marketing-paid-advertising.svg', 750000, 'intermediate', 'English', 1200, array['Structure Google Search, Performance Max and Meta campaigns', 'Set up conversion tracking and attribution correctly', 'Plan budgets from unit economics (CAC, AOV, margin, LTV)', 'Optimise bids, audiences and creative with test plans', 'Diagnose under-performing campaigns systematically']::text[], array['Digital marketing basics', 'Spreadsheet comfort']::text[], '[{"question": "Who is this course for?", "answer": "Plan, launch and optimise profitable Google and Meta ad campaigns. Level: Intermediate. Requirements: Digital marketing basics; Spreadsheet comfort."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, true, 10, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
