insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('07498a3b-0584-5bf4-aa8d-1ff2321ab56d', '5d9a9938-88d4-5c92-a45f-e3b9895491f8', 'bfb5aa68-429d-52eb-af5d-4531ce7d6043', 'a66564d3-9a11-5ec4-adec-8be02b8ccea2', 'Account audit questions', 'Answer the audit questions about the provided Google Ads account summary and prioritise fixes.

**Questions**
1. Identify the three most urgent problems in the Google Ads account summary.
2. Prioritise fixes by impact and effort.
3. How will you measure that the fixes worked?', 'document', 'Answer the audit questions about the provided Google Ads account summary and prioritise fixes.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:performance-marketing-paid-advertising/performance-marketing-paid-advertising-brief.docx', 'performance-marketing-paid-advertising-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('07498a3b-0584-5bf4-aa8d-1ff2321ab56d', '{
 "questions": [
  {
   "question": "Identify the three most urgent problems in the Google Ads account summary.",
   "key_points": [
    "Tracking/conversion issues",
    "Wasted spend on broad/irrelevant search terms",
    "Structure or bidding mismatched to goals"
   ]
  },
  {
   "question": "Prioritise fixes by impact and effort.",
   "key_points": [
    "Fix tracking first",
    "Negative keywords and restructuring",
    "Bidding and creative tests next"
   ]
  },
  {
   "question": "How will you measure that the fixes worked?",
   "key_points": [
    "Before/after CPA and ROAS on comparable periods",
    "Conversion volume and quality",
    "Search-term waste share"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('6f251edf-c79b-5b49-a3e6-dc9d29e0e50c', '43d00183-f871-596d-a183-9b68d71bf7e0', '5d9a9938-88d4-5c92-a45f-e3b9895491f8', 'Workbook assignment: Break-even ROAS model', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('b33c771e-f871-5315-aeee-60ec7668ebfb', '5d9a9938-88d4-5c92-a45f-e3b9895491f8', '6f251edf-c79b-5b49-a3e6-dc9d29e0e50c', '43d00183-f871-596d-a183-9b68d71bf7e0', 'Break-even ROAS model', 'Complete the unit-economics workbook: calculate break-even ROAS, target CAC and recommended daily budgets for three products.

**Tasks**
1. Calculate contribution per order after returns, shipping and payment fees.
2. Calculate contribution margin % and break-even ROAS (1 ÷ margin) per product.
3. Calculate target ROAS to keep a 10% profit margin after ads, and the maximum CAC per order.
4. Recommend daily budgets per product to hit the daily orders goal at target CAC.', 'file', 'Complete the unit-economics workbook: calculate break-even ROAS, target CAC and recommended daily budgets for three products.', null, 'Completed XLSX with working formulas', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:performance-marketing-paid-advertising/performance-marketing-paid-advertising-workbook.xlsx', 'performance-marketing-paid-advertising-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('b33c771e-f871-5315-aeee-60ec7668ebfb', '{
 "expected": {
  "Break-even ROAS — Cotton kurta": 2.21,
  "Break-even ROAS — Leather wallet": 1.74,
  "Break-even ROAS — Skincare kit": 1.71,
