insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('78e462d5-32c5-598e-a422-ad9a9e765564', '08616a85-38b9-582b-a15c-168d779ec504', 'single', null, 'Break-even ROAS equals…', '["1 ÷ gross margin", "Revenue ÷ clicks", "CTR × CPC", "Budget ÷ days"]'::jsonb, 0, null, 'At 40% margin, break-even ROAS is 1/0.4 = 2.5.', 1, 1) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('63c78c3c-15e9-5ea7-a6c8-1153d173d67a', '08616a85-38b9-582b-a15c-168d779ec504', 'multi', null, 'Which are valid reasons for falling ROAS after scaling? Select all that apply.', '["Audience saturation", "Rising frequency and creative fatigue", "Broader, less qualified targeting", "Better tracking"]'::jsonb, null, '[0, 1, 2]'::jsonb, 'Scaling often reaches less responsive users and fatigues creative.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
