-- SEO and Content Marketing
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('51911884-7474-5126-a3e5-1829955aeaea', 'seo-content-marketing', 'SEO and Content Marketing', 'Earn compounding traffic with search-led content strategy, technical SEO and authority building.', 'Plan content that people search for, write pages that rank and convert, fix technical issues and build authority. Includes keyword research, on-page SEO, content briefs, internal linking, technical audits and measurement.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/seo-content-marketing.svg', 750000, 'intermediate', 'English', 1200, array['Research keywords and map them to search intent', 'Write SEO content briefs and optimise pages on-page', 'Run technical SEO audits and prioritise fixes', 'Build internal linking and topical authority', 'Measure organic performance with Search Console and GA4']::text[], array['A website you can practise on (free options covered)']::text[], '[{"question": "Who is this course for?", "answer": "Earn compounding traffic with search-led content strategy, technical SEO and authority building. Level: Intermediate. Requirements: A website you can practise on (free options covered)."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 11, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
