insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('832f06bc-a0cf-5105-ae0e-cd3281fb9f35', '51911884-7474-5126-a3e5-1829955aeaea', '251788b7-6d8d-5f6d-ac36-6c61f2a7d19b', '90a0bdc2-abdf-52ad-a04e-7d0c524c6353', 'Content brief', 'Complete the content brief template for a target keyword chosen from the provided list.

**Questions**
