2. Outline H2/H3 structure and what each section answers.
3. Internal links, title tag and meta description.', 'document', 'Complete the content brief template for a target keyword chosen from the provided list.', null, 'Completed DOCX brief', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:seo-content-marketing/seo-content-marketing-brief.docx', 'seo-content-marketing-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
