insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('fbb7d3ad-a932-503c-a21d-6fc9a2b117e9', '51911884-7474-5126-a3e5-1829955aeaea', '48665c55-59ce-5296-ae90-fabb3c26a3f4', '9c91d936-ee2e-5634-ac82-60177e28d7a0', 'Keyword map', 'Cluster the 150 keywords in the workbook by intent and topic, assign each cluster to a page and prioritise by opportunity.

**Tasks**
1. Add an Intent column (Informational, Commercial, Transactional, Navigational).
2. Add a Topic cluster column and group keywords into 8–12 clusters.
3. Assign each cluster to one target URL (existing or new page).
4. Score opportunity = searches × (100 − difficulty) / 100 and rank clusters by total opportunity.
5. List your top three pages to create first.', 'file', 'Cluster the 150 keywords in the workbook by intent and topic, assign each cluster to a page and prioritise by opportunity.', null, 'Completed XLSX keyword map', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:seo-content-marketing/seo-content-marketing-workbook.xlsx', 'seo-content-marketing-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
