-- Social Media Marketing & Brand Building
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('c9934996-7b9d-56b5-a714-ea6e4272f0f0', 'social-media-marketing-brand-building', 'Social Media Marketing & Brand Building', 'Build a recognisable brand and an engaged community across Instagram, LinkedIn, YouTube and X.', 'Create a platform strategy, content pillars and a visual identity, then produce, publish and analyse content that grows reach and trust. Covers short-form video, creators, community management and social analytics.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/social-media-marketing-brand-building.svg', 750000, 'beginner', 'English', 960, array['Define brand positioning, voice and visual identity for social', 'Plan content pillars and a sustainable publishing calendar', 'Create short-form video and carousel content that performs', 'Work with creators and manage community conversations', 'Read social analytics and improve content systematically']::text[], array['A smartphone', 'Free Canva account']::text[], '[{"question": "Who is this course for?", "answer": "Build a recognisable brand and an engaged community across Instagram, LinkedIn, YouTube and X. Level: Beginner. Requirements: A smartphone; Free Canva account."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 12, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
