insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('cee24417-b252-5092-a262-e58939d8cd42', '{
 "questions": [
  {
   "question": "Define the café chain''s positioning in one sentence and three personality traits.",
   "key_points": [
    "Specific audience and differentiator",
    "Distinct traits",
    "Fits the new city''s context"
   ]
  },
  {
   "question": "Which platforms and content pillars would you use and why?",
   "key_points": [
    "Instagram/short video for discovery, maybe Google/WhatsApp for local",
    "3–5 pillars tied to brand",
    "Local community content"
   ]
  },
  {
   "question": "How will you measure brand-building progress in the first 90 days?",
   "key_points": [
    "Reach and follower growth in target city",
    "Engagement and saves/shares",
