insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('bf982897-161a-5726-a313-6985ac6a8856', 'c9934996-7b9d-56b5-a714-ea6e4272f0f0', 'e3e4390e-b9f2-59b3-a746-cba10c0cb5b0', 'f463bf87-d7c9-577a-acc8-5636b76d15f8', 'Content performance review', 'Analyse 60 days of post data in the workbook and identify which pillars, formats and hooks perform best.

**Tasks**
1. Calculate engagement rate (engagements ÷ reach) per post.
2. Summarise average reach and engagement rate by pillar, format and hook type (AVERAGEIFS or PivotTable).
3. Chart engagement rate by format.
4. Recommend the next month''s content mix with percentages.', 'file', 'Analyse 60 days of post data in the workbook and identify which pillars, formats and hooks perform best.', null, 'Completed XLSX with analysis', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:social-media-marketing-brand-building/social-media-marketing-brand-building-workbook.xlsx', 'social-media-marketing-brand-building-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
