-- Growth Marketing and Customer Acquisition
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('19751b11-9576-5597-a449-937ba7180831', 'growth-marketing-customer-acquisition', 'Growth Marketing and Customer Acquisition', 'Run disciplined growth experiments across the full funnel to acquire and retain customers.', 'Learn the growth model, North Star metrics, funnel analysis, experimentation and channel selection. Design and run experiments in acquisition, activation, retention and referral, and build a growth plan grounded in data.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/growth-marketing-customer-acquisition.svg', 750000, 'advanced', 'English', 1440, array['Build a growth model and choose a North Star metric', 'Analyse funnels and cohorts to find the biggest levers', 'Design, prioritise and run growth experiments', 'Select acquisition channels using economics and fit', 'Improve activation, retention and referral loops']::text[], array['Digital marketing fundamentals', 'Comfort with spreadsheets']::text[], '[{"question": "Who is this course for?", "answer": "Run disciplined growth experiments across the full funnel to acquire and retain customers. Level: Advanced. Requirements: Digital marketing fundamentals; Comfort with spreadsheets."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 13, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
