-- Marketing Analytics and Conversion Optimisation
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('215c74e8-237f-5711-a21d-4bc6ffb1022b', 'marketing-analytics-conversion-optimisation', 'Marketing Analytics and Conversion Optimisation', 'Measure what matters and turn more visitors into customers with evidence-based CRO.', 'Set up trustworthy tracking, build dashboards, analyse funnels and user behaviour, and run conversion experiments on landing pages, checkouts and forms. Learn the statistics you need without the jargon.', (select id from public.categories where slug = 'digital-marketing-growth'), '/thumbnails/marketing-analytics-conversion-optimisation.svg', 750000, 'advanced', 'English', 1440, array['Plan and implement a measurement framework and tracking plan', 'Build marketing dashboards in Looker Studio or Power BI', 'Diagnose conversion problems with funnels, heatmaps and recordings', 'Design A/B tests and read results correctly', 'Prioritise and communicate CRO opportunities']::text[], array['Marketing fundamentals', 'Spreadsheet skills']::text[], '[{"question": "Who is this course for?", "answer": "Measure what matters and turn more visitors into customers with evidence-based CRO. Level: Advanced. Requirements: Marketing fundamentals; Spreadsheet skills."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 14, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
