insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('85f3f3b1-146e-5e76-a21b-e7a8db6e368b', '215c74e8-237f-5711-a21d-4bc6ffb1022b', '22005f72-6605-59e1-ab35-90d799866679', '3b6c1bbb-5d87-5d33-a3fb-51a6a2f3fc1c', 'Funnel and A/B analysis', 'Use the workbook data to compute funnel drop-off by step and the conversion lift and significance of a checkout test.

**Tasks**
1. Calculate step-to-step conversion and drop-off for the funnel.
2. Identify the biggest drop-off step.
3. Calculate conversion rate for A and B, relative lift, and the z-score of a two-proportion test.
4. Recommend whether to ship B.', 'file', 'Use the workbook data to compute funnel drop-off by step and the conversion lift and significance of a checkout test.', null, 'Completed XLSX with calculations', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:marketing-analytics-conversion-optimisation/marketing-analytics-conversion-optimisation-workbook.xlsx', 'marketing-analytics-conversion-optimisation-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
