-- Advanced Excel for Professionals
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('7207ee90-31f7-5619-a9fb-13d08c1abb3d', 'advanced-excel-for-professionals', 'Advanced Excel for Professionals', 'Lookups, dynamic arrays, pivots, Power Query and dashboards — the Excel that gets work done.', 'Build fluency with the Excel skills used in finance, operations and analytics roles: modern lookups, dynamic arrays, data cleaning with Power Query, PivotTables, scenario analysis and interactive dashboards, all on realistic business workbooks.', (select id from public.categories where slug = 'professional-productivity'), '/thumbnails/advanced-excel-for-professionals.svg', 750000, 'intermediate', 'English', 1200, array['Use XLOOKUP, INDEX-MATCH, FILTER, UNIQUE and LET confidently', 'Clean and combine data with Power Query', 'Summarise data with PivotTables and PivotCharts', 'Run what-if, scenario and goal-seek analysis', 'Build a clean, interactive management dashboard']::text[], array['Microsoft Excel 2021 or Microsoft 365', 'Comfort with basic formulas']::text[], '[{"question": "Who is this course for?", "answer": "Lookups, dynamic arrays, pivots, Power Query and dashboards — the Excel that gets work done. Level: Intermediate. Requirements: Microsoft Excel 2021 or Microsoft 365; Comfort with basic formulas."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, true, 15, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
