insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('c7960546-bd6d-572e-a01c-ebc486807c83', '{
 "questions": [
  {
   "question": "Find the errors and risks in the colleague''s pricing model.",
   "key_points": [
    "Hard-coded numbers in formulas",
    "Inconsistent ranges/broken references",
    "No input/calculation separation"
   ]
  },
  {
   "question": "How would you restructure the model?",
   "key_points": [
    "Separate inputs, calculations, outputs",
    "Named ranges/Tables, consistent formulas",
    "Error checks"
   ]
  },
  {
   "question": "What checks would you add before sharing?",
   "key_points": [
    "Totals reconcile",
    "Error trapping (IFERROR used carefully)",
    "Peer review and version control"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
