insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('c754390f-6955-5d2f-abef-f96873a9443c', '7207ee90-31f7-5619-a9fb-13d08c1abb3d', 'ebe0df13-cafe-595f-a723-eb87e18f2f1c', '33453898-dfa8-5e9e-a81e-8bc8293b8a3d', 'Sales operations workbook', 'Solve the tasks in the workbook: lookups across sheets, a FILTER-based report, a PivotTable by region and month, and a scenario table.

**Tasks**
1. Convert both ranges to Excel Tables.
2. Add Product and Unit price to Orders with XLOOKUP; add Revenue = Quantity × Unit price.
3. Create a FILTER-based report on a new sheet showing West region orders above ₹20,000.
4. Build a PivotTable of revenue by Region and Month.
5. Build a scenario table: total revenue if prices rise 0%, 5% and 10%.', 'file', 'Solve the tasks in the workbook: lookups across sheets, a FILTER-based report, a PivotTable by region and month, and a scenario table.', null, 'Completed XLSX — formulas must be live, not typed values', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:advanced-excel-for-professionals/advanced-excel-for-professionals-workbook.xlsx', 'advanced-excel-for-professionals-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
