-- Excel Automation and AI Integration
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('52e9a12e-f3ec-580b-a7c2-9f3de4485386', 'excel-automation-ai-integration', 'Excel Automation and AI Integration', 'Automate repetitive spreadsheet work with macros, Office Scripts, Power Automate and AI.', 'Stop doing the same spreadsheet tasks every week. Record and edit VBA macros, write Office Scripts, connect Excel to Power Automate, and use AI (Copilot, Claude, ChatGPT) to write formulas, explain models and draft automation code safely.', (select id from public.categories where slug = 'professional-productivity'), '/thumbnails/excel-automation-ai-integration.svg', 750000, 'advanced', 'English', 1440, array['Record, read and edit VBA macros for routine tasks', 'Write Office Scripts for Excel on the web', 'Build Power Automate flows that move data in and out of Excel', 'Use AI to generate and explain formulas and code responsibly', 'Document and test spreadsheet automations']::text[], array['Advanced Excel skills (or our Advanced Excel course)', 'Microsoft 365 account for Office Scripts']::text[], '[{"question": "Who is this course for?", "answer": "Automate repetitive spreadsheet work with macros, Office Scripts, Power Automate and AI. Level: Advanced. Requirements: Advanced Excel skills (or our Advanced Excel course); Microsoft 365 account for Office Scripts."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 16, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
insert into public.course_modules (id, course_id, title, position) values ('b0cb2473-1ded-58ef-a1b5-22752cec8a0a', '52e9a12e-f3ec-580b-a7c2-9f3de4485386', 'Automation mindset', 1) on conflict (id) do update set title = excluded.title, position = excluded.position;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('6a75b084-1b02-556f-a3f8-35a289d5450f', 'b0cb2473-1ded-58ef-a1b5-22752cec8a0a', '52e9a12e-f3ec-580b-a7c2-9f3de4485386', 'Spotting repetitive tasks', 'text', '**Module 1, lesson 1** · Automation mindset

