insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('31f1eaaa-5f0a-5582-a674-de27b8b6cff2', '52e9a12e-f3ec-580b-a7c2-9f3de4485386', '502cedd7-319e-5af8-a656-78e87920a689', 'cb0de950-995a-594b-a407-13e899f7a74c', 'Code review questions', 'Review the AI-generated VBA in the brief, identify bugs and risks and answer the questions.

**Questions**
1. Identify bugs in the AI-generated VBA.
2. Identify risks of running it as-is.
3. Rewrite or describe the safer version.', 'document', 'Review the AI-generated VBA in the brief, identify bugs and risks and answer the questions.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:excel-automation-ai-integration/excel-automation-ai-integration-brief.docx', 'excel-automation-ai-integration-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('31f1eaaa-5f0a-5582-a674-de27b8b6cff2', '{
 "questions": [
  {
   "question": "Identify bugs in the AI-generated VBA.",
   "key_points": [
    "Uses ActiveSheet/Select without checks",
    "Hard-coded ranges that miss new rows",
    "No error handling"
   ]
  },
  {
   "question": "Identify risks of running it as-is.",
   "key_points": [
    "Deleting/overwriting data on wrong sheet",
    "Silent failures",
    "Macro security"
   ]
  },
  {
   "question": "Rewrite or describe the safer version.",
   "key_points": [
    "Explicit worksheet references",
    "Dynamic last row",
    "Backup/confirmation and error handling"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
