insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('03967a84-206b-5c72-ac2c-038e5a78d6b0', '52e9a12e-f3ec-580b-a7c2-9f3de4485386', 'fe255c0f-85bc-567f-a4ba-bd8d14a267f7', 'c7095671-5243-5ee6-a701-483880486718', 'Macro-ready monthly report', 'Use the workbook to automate the monthly consolidation: write or record a macro (or Office Script) that combines the three regional sheets and formats the report.

**Tasks**
1. Write a macro or Office Script that combines the three regional sheets into one ''Combined'' sheet with a Region column.
2. The automation must find the last row dynamically and must not touch any other sheet.
3. Add a ''Report'' sheet with totals by region and channel, formatted as a table.
4. Paste your code into a ''Code'' sheet (or submit it as a .txt/.bas file) with comments.', 'file', 'Use the workbook to automate the monthly consolidation: write or record a macro (or Office Script) that combines the three regional sheets and formats the report.', null, 'Macro-enabled or script-backed workbook (XLSX/XLSM zipped) plus code listing', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:excel-automation-ai-integration/excel-automation-ai-integration-workbook.xlsx', 'excel-automation-ai-integration-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
