insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('aba5e85f-609f-57f2-ae5e-600797c5d2cb', '52e9a12e-f3ec-580b-a7c2-9f3de4485386', 'a0633b7f-a499-5489-a454-0c9656130f6a', 'fc6266a7-8996-5e29-a8f8-6aa91d9b0125', 'The macro that deleted data', 'Read the scenario, then write your response. State your assumptions, then give your diagnosis, recommended actions and the risks.', 'scenario', 'Scenario challenge: respond as the decision-maker.', 'A shared macro deleted three months of entries when run on the wrong sheet. Explain the failure and add safeguards.', 'Written analysis with improved code approach', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Diagnosis", "points": 30, "description": "Identifies the real causes, not just symptoms."}, {"criterion": "Recommended actions", "points": 30, "description": "Concrete, prioritised, realistic actions."}, {"criterion": "Risks and trade-offs", "points": 20, "description": "Considers risks, stakeholders and alternatives."}, {"criterion": "Communication", "points": 20, "description": "Clear, structured and persuasive for the stated audience."}]'::jsonb, 100, 50, null, null, array['docx', 'pdf']::text[], true, false, true, 60, 13, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
