-- Power BI and Business Intelligence
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('a827b5fb-c255-5b5d-a2f0-5ff13bb60097', 'power-bi-business-intelligence', 'Power BI and Business Intelligence', 'Model data, write DAX and design dashboards decision-makers actually use.', 'Learn the full Power BI workflow: Power Query, star-schema modelling, DAX measures, visual design, row-level security and publishing. You build an end-to-end sales and operations report from raw data.', (select id from public.categories where slug = 'professional-productivity'), '/thumbnails/power-bi-business-intelligence.svg', 750000, 'intermediate', 'English', 1200, array['Import and transform data with Power Query', 'Design star-schema data models with correct relationships', 'Write DAX measures including time intelligence', 'Design clear, accessible report pages', 'Publish, share and secure reports in Power BI Service']::text[], array['Windows PC with Power BI Desktop (free)', 'Excel basics']::text[], '[{"question": "Who is this course for?", "answer": "Model data, write DAX and design dashboards decision-makers actually use. Level: Intermediate. Requirements: Windows PC with Power BI Desktop (free); Excel basics."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 17, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
