insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('433294e9-2625-5e0f-aba8-b929d20c62a5', 'a827b5fb-c255-5b5d-a2f0-5ff13bb60097', '8b507edf-b9e3-544f-a881-70250d5952f7', '80463b24-66bd-5c64-afcd-eb8bda8731e4', 'DAX reasoning questions', 'Answer the DAX questions on filter context and time intelligence in the brief.

**Questions**
1. Explain filter context and how CALCULATE changes it.
2. Write a measure for revenue year-to-date and same period last year.
3. Why might a YoY measure show blanks?', 'document', 'Answer the DAX questions on filter context and time intelligence in the brief.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:power-bi-business-intelligence/power-bi-business-intelligence-brief.docx', 'power-bi-business-intelligence-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
