insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('68f8bb26-c232-5d62-a594-77bb91680a59', 'a827b5fb-c255-5b5d-a2f0-5ff13bb60097', 'bc39c4f4-1c8b-588b-ac66-dbb636ec00be', '32b54cd7-63a6-5b59-ab6e-38e78a31a4f1', 'Star schema design', 'Use the workbook''s flat sales extract to design dimension and fact tables and document keys and relationships.

**Tasks**
1. Design a star schema: list the fact table and each dimension table with their columns and keys on a ''Model design'' sheet.
2. Create the dimension tables (Customer, Product, Date) as separate sheets with unique keys (use UNIQUE).
3. Create the fact table with only keys and measures.
4. Document each relationship (from, to, cardinality, direction).
5. Explain which DAX measures you would create first.', 'file', 'Use the workbook''s flat sales extract to design dimension and fact tables and document keys and relationships.', null, 'Completed XLSX with the model design sheets', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:power-bi-business-intelligence/power-bi-business-intelligence-workbook.xlsx', 'power-bi-business-intelligence-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
