-- Financial Modelling and Business Analysis
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('25d05384-7f78-58f0-ac4b-cc08514bdc02', 'financial-modelling-business-analysis', 'Financial Modelling and Business Analysis', 'Build three-statement models, forecasts and valuations the way analysts do.', 'Learn to read financial statements, build a linked three-statement model, forecast drivers, run scenarios and value a business with DCF and multiples. Focus on clean structure, checks and clear presentation of assumptions.', (select id from public.categories where slug = 'professional-productivity'), '/thumbnails/financial-modelling-business-analysis.svg', 750000, 'advanced', 'English', 1440, array['Analyse income statements, balance sheets and cash flows', 'Build an integrated three-statement model with checks', 'Forecast revenue and costs from business drivers', 'Value a company using DCF and trading multiples', 'Present scenarios and sensitivities to decision makers']::text[], array['Strong Excel skills', 'Basic accounting knowledge helpful']::text[], '[{"question": "Who is this course for?", "answer": "Build three-statement models, forecasts and valuations the way analysts do. Level: Advanced. Requirements: Strong Excel skills; Basic accounting knowledge helpful."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, true, 18, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
