insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('6e404cc9-4b8c-5f0a-ab9a-465218d98d94', '25d05384-7f78-58f0-ac4b-cc08514bdc02', 'bd5ecab6-458d-5fc0-af0a-ddab2bc985f5', '87228e76-3258-523c-a7c9-0797a3402dc9', 'Three-statement model', 'Complete the model in the workbook: forecast five years from the driver sheet so the balance sheet balances and the cash flow reconciles.

**Tasks**
1. Build the forecast income statement for FY26–FY30 from the drivers.
2. Build the balance sheet with working capital from day counts, fixed assets roll-forward and debt schedule.
3. Build the cash flow statement; cash on the balance sheet must come from the cash flow.
4. Add a balance check row (Assets − Liabilities − Equity) that equals zero every year.
5. Add a summary with revenue, EBITDA margin and free cash flow.', 'file', 'Complete the model in the workbook: forecast five years from the driver sheet so the balance sheet balances and the cash flow reconciles.', null, 'Completed XLSX — balance check must equal zero in every year', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:financial-modelling-business-analysis/financial-modelling-business-analysis-workbook.xlsx', 'financial-modelling-business-analysis-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
