insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('f89bf5ee-9059-5b57-a7ee-0fbc2b7ea348', 'advanced-powerpoint-business-presentations', 'Advanced PowerPoint and Business Presentations', 'Structure arguments and design decks that executives understand in minutes.', 'Learn the storytelling and design habits of consulting-style decks: pyramid principle, action titles, clean data charts, master slides and delivery. Rebuild real business decks and present with confidence.', (select id from public.categories where slug = 'professional-productivity'), '/thumbnails/advanced-powerpoint-business-presentations.svg', 750000, 'intermediate', 'English', 1200, array['Structure presentations with the pyramid principle and storylines', 'Write action titles that carry the argument', 'Design clean slides with masters, grids and consistent styles', 'Turn data into clear charts and tables', 'Deliver and handle questions confidently']::text[], array['Microsoft PowerPoint or Google Slides']::text[], '[{"question": "Who is this course for?", "answer": "Structure arguments and design decks that executives understand in minutes. Level: Intermediate. Requirements: Microsoft PowerPoint or Google Slides."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 2, false, 19, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
