insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('ef11a6f8-3053-5e98-a36d-d521d0ae8742', 'f89bf5ee-9059-5b57-a7ee-0fbc2b7ea348', '7e86fd16-d580-509e-a7b0-ee9f6da3245f', '75430c13-53e1-50ed-a496-3e890221c576', 'Storyline exercise', 'Answer the storyline questions and write the executive summary for the market-entry case in the brief.

**Questions**
1. Write the governing thought for the market-entry case.
2. Write the three key supporting arguments with evidence.
3. Write the executive summary slide text.', 'document', 'Answer the storyline questions and write the executive summary for the market-entry case in the brief.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:advanced-powerpoint-business-presentations/advanced-powerpoint-business-presentations-brief.docx', 'advanced-powerpoint-business-presentations-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
