insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('9b16c82c-268e-5f1e-a405-ebdc7bfb42c2', 'f89bf5ee-9059-5b57-a7ee-0fbc2b7ea348', '699b1e85-ab14-5531-aaf9-b21fd3d83ef5', 'eb227219-87fd-5305-ab49-30ddb5211ee5', 'Chart makeover data', 'Use the workbook data to build three corrected charts that fix the problems listed and export them for slides.

**Tasks**
1. Build a line chart showing the trend of each segment over the year, labelled directly (no legend).
2. Build a bar chart comparing full-year totals by segment, sorted.
3. Build a chart that highlights Consumer''s decline (grey other series, colour Consumer).
4. Give each chart an action title that states the message.', 'file', 'Use the workbook data to build three corrected charts that fix the problems listed and export them for slides.', null, 'Completed XLSX with the three charts', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:advanced-powerpoint-business-presentations/advanced-powerpoint-business-presentations-workbook.xlsx', 'advanced-powerpoint-business-presentations-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
