insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('2317e164-8518-5d95-ad82-9b9607c4dd61', 'f89bf5ee-9059-5b57-a7ee-0fbc2b7ea348', '9c756437-7733-55fd-ab46-ba86e4381252', '044e5dde-ced5-5469-a1ab-f4a981a902fc', 'Board-ready deck', 'Rebuild the provided messy 12-slide deck (or your own) into a clear, consistent 8–10 slide deck.

Use a real or realistic business. Do not invent results: if something did not work, say so and explain what you learned.', 'practical', 'Rebuild the provided messy 12-slide deck (or your own) into a clear, consistent 8–10 slide deck.', null, 'PPTX or PDF of before and after', 'Accepted: PDF, DOCX, PPTX, XLSX, PNG, JPG, ZIP. Maximum 20 MB.', '[{"criterion": "Completeness of deliverable", "points": 30, "description": "Everything requested in the deliverables list is submitted."}, {"criterion": "Quality of execution", "points": 30, "description": "The work meets a professional standard and applies course methods."}, {"criterion": "Evidence of real work", "points": 20, "description": "Screenshots, links, files or results show the work was actually done."}, {"criterion": "Reflection and learning", "points": 20, "description": "Honest reflection on what worked, what did not and what to change."}]'::jsonb, 100, 50, null, null, array['pdf', 'docx', 'pptx', 'xlsx', 'png', 'jpg', 'zip']::text[], true, true, true, 180, 12, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
