insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('65b87f1d-9287-54f6-ae66-50993bd0d592', 'f89bf5ee-9059-5b57-a7ee-0fbc2b7ea348', '7600c322-d6d3-5728-a2ba-3d7607c36a9c', '0b026568-ffe8-5cdb-a727-25541aa0fcbc', 'Five minutes with the CEO', 'Read the scenario, then write your response. State your assumptions, then give your diagnosis, recommended actions and the risks.', 'scenario', 'Scenario challenge: respond as the decision-maker.', 'Your 30-minute slot is cut to five minutes. Explain how you restructure and what you present.', 'Written plan and the 3 slides you would keep', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Diagnosis", "points": 30, "description": "Identifies the real causes, not just symptoms."}, {"criterion": "Recommended actions", "points": 30, "description": "Concrete, prioritised, realistic actions."}, {"criterion": "Risks and trade-offs", "points": 20, "description": "Considers risks, stakeholders and alternatives."}, {"criterion": "Communication", "points": 20, "description": "Clear, structured and persuasive for the stated audience."}]'::jsonb, 100, 50, null, null, array['docx', 'pdf']::text[], true, false, true, 60, 13, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
