insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('f30a853a-0fc1-5703-af32-f6d9d11696fa', 'ca344d8b-26fc-52d8-a037-4456a08bc8f5', 'multi', null, 'Which declutter a chart? Select all that apply.', '["Remove heavy gridlines", "Label data directly", "Add 3D effects", "Highlight the key series"]'::jsonb, null, '[0, 1, 3]'::jsonb, '3D effects distort data.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
