insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('282817c3-28b6-5da6-ad44-3affcac1cd7d', 'ca344d8b-26fc-52d8-a037-4456a08bc8f5', 'match', null, 'Match the data question to the best chart.', '{"left": ["Trend over time", "Part of a whole", "Comparison across categories"], "right": ["Stacked bar or simple pie", "Line chart", "Bar chart"]}'::jsonb, null, '[1, 0, 2]'::jsonb, 'Chart type follows the question.', 2, 4) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('8ee71f96-d98c-546c-a4d8-25ab1f3b4bab', 'ca344d8b-26fc-52d8-a037-4456a08bc8f5', 'scenario', 'An executive interrupts on slide 2 asking for the recommendation.', 'What should you do?', '["Ask them to wait", "Give the recommendation now and adapt the flow", "Skip to the last slide silently", "End the meeting"]'::jsonb, 1, null, 'Answer first; executives want the conclusion.', 2, 5) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;

-- Data Analytics for Business Professionals
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('5f117d2c-e740-5ead-a134-cc5c4523975e', 'data-analytics-for-business-professionals', 'Data Analytics for Business Professionals', 'Ask better questions of data and answer them with Excel, SQL basics and clear storytelling.', 'A practical analytics course for non-specialists: framing questions, cleaning data, descriptive statistics, SQL fundamentals, visualisation and communicating insights. Work on retail, marketing and operations datasets throughout.', (select id from public.categories where slug = 'professional-productivity'), '/thumbnails/data-analytics-for-business-professionals.svg', 750000, 'beginner', 'English', 960, array['Turn business problems into answerable data questions', 'Clean and prepare data reliably', 'Use descriptive statistics and basic SQL queries', 'Visualise data to reveal patterns honestly', 'Communicate insights and recommendations clearly']::text[], array['Excel or Google Sheets', 'No coding required (SQL taught from scratch)']::text[], '[{"question": "Who is this course for?", "answer": "Ask better questions of data and answer them with Excel, SQL basics and clear storytelling. Level: Beginner. Requirements: Excel or Google Sheets; No coding required (SQL taught from scratch)."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 20, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
