insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('f344c494-aaeb-5085-a7eb-dd91aaeaddee', '{
 "questions": [
  {
   "question": "Restate the delivery delay problem as a specific analysis question.",
   "key_points": [
    "Measurable outcome (e.g., % late deliveries)",
    "Scope and time period",
    "Decision it informs"
   ]
  },
  {
   "question": "Which metrics and data do you need?",
   "key_points": [
    "On-time rate, delay minutes, by route/driver/time",
    "Order, dispatch and delivery timestamps",
    "Definitions agreed"
   ]
  },
  {
   "question": "What are possible causes and how would you test them?",
   "key_points": [
    "Hypotheses: traffic times, warehouse dispatch, routes, staffing",
    "Segment comparisons",
    "Avoid causal claims without evidence"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
