insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('912e0173-46ff-5983-aa24-0cfc750e6132', '5f117d2c-e740-5ead-a134-cc5c4523975e', 'a318c88a-2492-55f0-ab72-fec31c45d5b2', '7229b5fc-34f1-5133-a9d3-66bfebd2b7f8', 'Retail sales analysis', 'Clean the retail dataset in the workbook, then answer the five business questions with formulas and pivots.

**Tasks**
1. Remove duplicate transactions, standardise Store and Category text, and handle blank prices (exclude and count them). Log every step on a ''Cleaning log'' sheet.
2. Add Revenue = Units × Unit price.
3. Answer: total revenue, revenue by category, best store, average basket value, and number of excluded rows.', 'file', 'Clean the retail dataset in the workbook, then answer the five business questions with formulas and pivots.', null, 'Completed XLSX with a cleaning log and answers', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:data-analytics-for-business-professionals/data-analytics-for-business-professionals-workbook.xlsx', 'data-analytics-for-business-professionals-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
