insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('5b3adf01-270f-5915-a17d-7265ceab771e', '09a343c9-748e-58b3-ab00-6bea8f92a910', '3a4a8a70-4bda-59f6-a706-27b09f2a8f17', '418c6046-5a58-51a6-a3cb-5b9ab5d6d67e', 'Unit economics and break-even', 'Complete the workbook for a cloud-kitchen idea: contribution margin, break-even orders per month and sensitivity to price and food cost.

**Tasks**
1. Calculate contribution per order and contribution margin %.
2. Calculate total monthly fixed costs and break-even orders per month and per day (30 days).
3. Build a two-way data table: break-even orders/day for AOV ₹280–₹400 and food cost 28%–36%.
4. Recommend two levers to reach break-even faster.', 'file', 'Complete the workbook for a cloud-kitchen idea: contribution margin, break-even orders per month and sensitivity to price and food cost.', null, 'Completed XLSX with formulas', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:startup-launch-business-fundamentals/startup-launch-business-fundamentals-workbook.xlsx', 'startup-launch-business-fundamentals-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
