insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('04b3bd38-3ffc-5e29-ac8c-e220ffebe15f', '3e4b3c05-2578-59b9-a9ea-08fd9f9af124', 'multi', null, 'Which are strong validation signals? Select all that apply.', '["Pre-orders or deposits", "Repeat interviews describing the same pain", "Friends saying ''nice idea''", "Waitlist sign-ups with follow-up engagement"]'::jsonb, null, '[0, 1, 3]'::jsonb, 'Commitment beats compliments.', 2, 2) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
