insert into public.quiz_questions (id, quiz_id, qtype, context, prompt, options, correct_index, correct, explanation, points, position) values ('a5722a6c-ae00-58ee-ac61-f13490bacdb2', '3e4b3c05-2578-59b9-a9ea-08fd9f9af124', 'fill_blank', null, 'Fixed costs of ₹1,20,000 and contribution of ₹200 per unit give a break-even of ___ units.', null, null, '[["600"]]'::jsonb, '1,20,000 ÷ 200 = 600.', 1, 4) on conflict (id) do update set qtype = excluded.qtype, context = excluded.context, prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, correct = excluded.correct, explanation = excluded.explanation, points = excluded.points, position = excluded.position;
