-- Business Development and Sales Mastery
insert into public.courses (id, slug, title, subtitle, description, category_id, thumbnail_url, price_paise, level, language, duration_minutes, learning_outcomes, requirements, faqs, status, rights_status, rights_notes, is_demo, published_at, projects_count, is_featured, sort_order, completion_requires_all_lessons, completion_requires_assignments, completion_min_quiz_pct) values ('9e059c81-965e-53c5-a518-69f357c38915', 'business-development-sales-mastery', 'Business Development and Sales Mastery', 'Prospect, run discovery, pitch, negotiate and close — with a repeatable process.', 'A structured B2B and B2C sales course: ideal customer profiles, prospecting, discovery questions, value-based pitching, objection handling, negotiation, pipeline management and partnerships. Practise with role-plays and real outreach.', (select id from public.categories where slug = 'entrepreneurship-business'), '/thumbnails/business-development-sales-mastery.svg', 750000, 'intermediate', 'English', 1200, array['Define ideal customer profiles and target accounts', 'Prospect through email, LinkedIn and calls professionally', 'Run discovery calls that uncover real needs', 'Handle objections and negotiate win–win terms', 'Manage a pipeline and forecast with a CRM']::text[], array['No prior sales experience required']::text[], '[{"question": "Who is this course for?", "answer": "Prospect, run discovery, pitch, negotiate and close — with a repeatable process. Level: Intermediate. Requirements: No prior sales experience required."}, {"question": "How are assignments evaluated?", "answer": "Quizzes are marked instantly. Workbook, written, practical and scenario assignments are evaluated against a published rubric, usually about an hour after you submit. Results include marks and written feedback, and the Proofwork team can review and adjust any result."}, {"question": "How long do I have access?", "answer": "Access does not expire. Learn at your own pace and come back to the material whenever you need it."}, {"question": "Is there a certificate?", "answer": "You receive an internal Proofwork completion record when you finish the course requirements. It is not an accredited qualification."}, {"question": "How do I pay?", "answer": "The course costs ₹7,500. Pay securely with UPI, cards, net banking or wallets through Razorpay. Access is granted as soon as your payment is verified."}, {"question": "Can I get a refund?", "answer": "Yes, within 7 days of purchase if you have completed less than 25% of the course. See the refund policy for full conditions."}]'::jsonb, 'published', 'owned', 'Original Proofwork course content.', false, now(), 3, false, 22, false, true, 60) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, category_id = excluded.category_id, thumbnail_url = coalesce(public.courses.thumbnail_url, excluded.thumbnail_url), level = excluded.level, duration_minutes = excluded.duration_minutes, learning_outcomes = excluded.learning_outcomes, requirements = excluded.requirements, faqs = excluded.faqs, projects_count = excluded.projects_count, sort_order = excluded.sort_order;
