insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('66df6ad0-d183-5f63-a79b-c98ff741976f', '9e059c81-965e-53c5-a518-69f357c38915', 'fba41083-688e-5c4c-a84d-c72f935e5c72', 'facd5049-6557-5323-a56b-c1609d4b4420', 'Discovery call plan', 'Answer the discovery planning questions for a SaaS sale to a 200-person logistics company.

**Questions**
1. What do you need to learn in discovery?
2. Write five discovery questions.
3. How will you decide whether to proceed after the call?', 'document', 'Answer the discovery planning questions for a SaaS sale to a 200-person logistics company.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:business-development-sales-mastery/business-development-sales-mastery-brief.docx', 'business-development-sales-mastery-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('66df6ad0-d183-5f63-a79b-c98ff741976f', '{
 "questions": [
  {
   "question": "What do you need to learn in discovery?",
   "key_points": [
    "Current process and pain",
    "Impact/cost of the problem",
    "Decision process, budget and timeline"
   ]
  },
  {
