insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('00005feb-85c7-5d50-ae52-2989c3410afd', '9e059c81-965e-53c5-a518-69f357c38915', 'e58f7e0e-1f2f-5ec3-ad1b-226abc76a523', 'f021ac0a-4b03-5ffc-a7f8-f04542f0ab3b', 'Pipeline forecast', 'Use the CRM export in the workbook to calculate weighted pipeline by stage and forecast the quarter.

**Tasks**
1. Look up each deal''s stage probability and calculate weighted value.
2. Summarise weighted pipeline by stage and by owner.
3. Forecast Q4 2026 (deals expected to close by 31 Dec 2026).
4. Flag deals that need requalification and say why.', 'file', 'Use the CRM export in the workbook to calculate weighted pipeline by stage and forecast the quarter.', null, 'Completed XLSX with weighted forecast', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:business-development-sales-mastery/business-development-sales-mastery-workbook.xlsx', 'business-development-sales-mastery-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
