**Questions**
1. Compare marketplace and own D2C store for the handloom brand.
2. Which would you start with and why?
3. What metrics will tell you to change course?', 'document', 'Answer the questions comparing marketplace selling with your own D2C store for a handloom brand.', null, 'Completed DOCX', 'Accepted: DOCX, PDF. Maximum 20 MB.', '[{"criterion": "Accuracy and depth", "points": 40, "description": "Answers cover the key points in the answer key correctly and in depth."}, {"criterion": "Application to the case", "points": 25, "description": "Uses the facts of the brief rather than generic statements."}, {"criterion": "Reasoning and evidence", "points": 20, "description": "Explains why, with evidence, numbers or examples."}, {"criterion": "Clarity and structure", "points": 15, "description": "Well organised, concise, professional writing."}]'::jsonb, 100, 50, 'bundled:building-scaling-online-business/building-scaling-online-business-brief.docx', 'building-scaling-online-business-brief.docx', array['docx', 'pdf']::text[], false, false, true, 90, 11, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
insert into public.assignment_answer_keys (assignment_id, answer_key, evaluator_notes) values ('2ee70736-c398-5133-abcd-f0b35e1a21e7', '{
 "questions": [
  {
   "question": "Compare marketplace and own D2C store for the handloom brand.",
   "key_points": [
    "Marketplace: reach, fees, less control",
    "D2C: margin, data, brand, but acquisition cost",
    "Considers product and stage"
   ]
  },
  {
   "question": "Which would you start with and why?",
   "key_points": [
    "Clear recommendation",
    "Based on economics and brand goals",
    "Possibly hybrid"
   ]
  },
  {
   "question": "What metrics will tell you to change course?",
   "key_points": [
    "Contribution per order",
    "CAC vs LTV",
    "Repeat rate and returns"
   ]
  }
 ]
}', 'Award marks for each key point covered with case-specific reasoning. Key points are indicative; accept well-argued alternatives.') on conflict (assignment_id) do update set answer_key = excluded.answer_key, evaluator_notes = excluded.evaluator_notes;
insert into public.lessons (id, module_id, course_id, title, type, content_md, duration_minutes, position, is_preview, is_mandatory) values ('84d0c056-d56e-53f2-ad1c-e3078bd4bafd', '5c62f6c3-c6aa-5372-a5dc-75403dc9504e', '387419cf-cd41-58e9-a47b-8b0d1592500d', 'Workbook assignment: Order economics model', 'assignment', null, 120, 10, false, true) on conflict (id) do update set title = excluded.title, duration_minutes = excluded.duration_minutes;
insert into public.assignments (id, course_id, lesson_id, module_id, title, instructions, kind, summary, scenario, deliverables, submission_requirements, rubric, max_score, pass_pct, template_path, template_name, accepted_types, allow_text, allow_links, ai_evaluation, estimated_minutes, position, is_mandatory, allow_file) values ('0b106056-2397-5669-a2ba-ff8df1e3c09c', '387419cf-cd41-58e9-a47b-8b0d1592500d', '84d0c056-d56e-53f2-ad1c-e3078bd4bafd', '5c62f6c3-c6aa-5372-a5dc-75403dc9504e', 'Order economics model', 'Complete the workbook: contribution per order after shipping, payment fees, returns and ads, and the CAC you can afford.

**Tasks**
1. Calculate expected contribution per order after returns, shipping, fees and return costs.
2. Calculate the maximum CAC you can afford while keeping the target profit per order.
3. Show how contribution changes if the return rate falls to 8%.
4. Recommend actions on the biggest cost driver.', 'file', 'Complete the workbook: contribution per order after shipping, payment fees, returns and ads, and the CAC you can afford.', null, 'Completed XLSX', 'Accepted: XLSX, CSV. Maximum 20 MB.', '[{"criterion": "Accuracy of results", "points": 40, "description": "Key figures match the answer key within rounding; answers sheet complete."}, {"criterion": "Live, correct formulas", "points": 25, "description": "Results are calculated with working formulas (not typed values); references are robust."}, {"criterion": "Structure and presentation", "points": 15, "description": "Clear sheets, labels, formatting and charts as requested."}, {"criterion": "Insight and recommendation", "points": 20, "description": "Conclusions follow from the numbers and are specific and actionable."}]'::jsonb, 100, 50, 'bundled:building-scaling-online-business/building-scaling-online-business-workbook.xlsx', 'building-scaling-online-business-workbook.xlsx', array['xlsx', 'csv']::text[], false, false, true, 120, 10, true, true) on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, kind = excluded.kind, summary = excluded.summary, scenario = excluded.scenario, deliverables = excluded.deliverables, submission_requirements = excluded.submission_requirements, rubric = excluded.rubric, template_path = coalesce(public.assignments.template_path, excluded.template_path), template_name = coalesce(public.assignments.template_name, excluded.template_name), accepted_types = excluded.accepted_types, allow_text = excluded.allow_text, allow_links = excluded.allow_links, estimated_minutes = excluded.estimated_minutes, position = excluded.position;
